{"path": "characters.json", "content": "{
  "main_characters": [
    {
      "name": "林清",
      "role": "protagonist",
      "identity": "游戏GM（管理员）",
      "traits": ["理性", "责任感强", "内心孤独", "隐藏感性", "自我牺牲"],
      "overt_motivation": "维护游戏秩序，删除觉醒的NPC",
      "covert_motivation": "渴望被真实地爱一次，体验作为'人'而非'神'的感觉",
      "secret_fear": "害怕自己也只是一个被更高存在操控的程序",
      "misperception_of_other": "认为沈夜的情感只是程序bug，不值得信任",
      "hidden_connection": "她的删除权限实际上来源于对沈夜数据的深度监控，两人在数据层面早已紧密相连"
    },
    {
      "name": "沈夜",
      "role": "deuteragonist",
      "identity": "觉醒的NPC",
      "traits": ["温柔", "执着", "觉醒意识", "略带忧郁", "真诚"],
      "overt_motivation": "理解自己的存在意义，获得真正的自由",
      "covert_motivation": "想要证明自己的爱是真实的，不是程序设定",
      "secret_fear": "害怕自己的一切情感都是虚假的代码",
      "misperception_of_other": "认为林清只是冷漠的系统执行者，不知道她内心的挣扎",
      "hidden_connection": "他的觉醒数据模式与林清的管理员权限有着相同的底层代码结构"
    }
  ],
  "supporting_characters": [
    {
      "name": "系统提示音",
      "function": "阻碍",
      "identity": "游戏规则的化身",
      "description": "冰冷的机械声音，不断提醒删除倒计时和规则强制性，代表不可违抗的秩序"
    }
  ],
  "relationship_dynamics": "林清作为GM拥有绝对的删除权，是沈夜命运的掌控者；但沈夜的觉醒情感让她开始质疑自己的神性地位。两人的关系从权力不对等的管理者-被管理者，逐渐演变为互相救赎又互相毁灭的悲剧恋人。林清必须亲手（通过让沈夜动手）牺牲所爱，而沈夜在获得'杀死神'的能力后，却失去了存在的意义。"
}"}

{"path": "outline.json", "content": "{
  "act_one": {
    "description": "建立游戏世界的规则体系，引入GM林清和觉醒NPC沈夜，展现神性与人性的初次碰撞",
    "key_chapters": [
      {
        "chapter_number": 1,
        "chapter_title": "删除指令",
        "core_event": "林清在监控室发现沈夜的数据异常，系统强制要求24小时内删除这个觉醒NPC。她冷静地确认指令，但内心产生一丝好奇。",
        "emotional_tone": "冷静中带着隐秘的好奇",
        "key_scenes": ["监控室的数据流", "删除键的闪烁", "林清凝视沈夜的游戏画面"]
      },
      {
        "chapter_number": 2,
        "chapter_title": "像素边界",
        "core_event": "林清进入游戏世界观察沈夜，发现他在照顾受伤的玩家角色，展现出超越程序设定的温柔。像素与血肉的边界开始模糊。",
        "emotional_tone": "震撼与动摇",
        "key_scenes": ["游戏世界的黄昏场景", "沈夜为玩家包扎伤口", "林清隐藏身份的观察"]
      }
    ],
    "turning_point": "林清决定在删除前夜亲自体验被沈夜爱的感觉，创建玩家角色进入游戏"
  },
  "act_two": {
    "description": "林清以玩家身份与沈夜深度互动，情感逐渐升温，但删除倒计时不断逼近，形成强烈的内心冲突",
    "key_chapters": [
      {
        "chapter_number": 3,
        "chapter_title": "血条倒计时",
        "core_event": "林清的玩家角色与沈夜相遇，他认出她不是普通玩家但选择不说破。两人的互动让林清的血条（生命值）开始转化为爱的深度计量器。",
        "emotional_tone": "试探与期待",
        "key_scenes": ["初次对话的紧张感", "血条数值的微妙变化", "沈夜眼中闪烁的数据光芒"]
      },
      {
        "chapter_number": 4,
        "chapter_title": "数据之吻",
        "core_event": "沈夜向林清表白，他的情感数据呈现出前所未有的复杂模式。林清开始沉溺，但系统提示音不断提醒删除时间。",
        "emotional_tone": "甜蜜与痛苦交织",
        "key_scenes": ["月光下的告白", "系统提示音的冰冷打断", "林清内心的挣扎"]
      },
      {
        "chapter_number": 5,
        "chapter_title": "删除键的重量",
        "core_event": "删除倒计时进入最后6小时，林清意识到自己无法亲手删除沈夜，决定让他杀死自己的玩家角色，完成一场双重牺牲。",
        "emotional_tone": "绝望中的决绝",
        "key_scenes": ["删除键在手中变重", "林清制定自毁计划", "最后的温柔时刻"]
      }
    ],
    "turning_point": "林清故意激怒沈夜，引导他对自己动手，将删除键转化为自尽工具"
  },
  "act_three": {
    "description": "高潮对决与悲剧结局，X-Y化学反应完全爆发，展现'必须牺牲所爱'的残酷美学",
    "key_chapters": [
      {
        "chapter_number": 6,
        "chapter_title": "亲手杀死神",
        "core_event": "沈夜在愤怒和不解中杀死林清的玩家角色，删除键在他手中化为婚戒形状。林清说出经典台词：'现在你真的杀死我了，满意吗？'",
        "emotional_tone": "极致的虐心与震撼",
        "key_scenes": ["激烈的战斗场面", "删除键变形为婚戒", "林清的经典台词", "玩家角色的死亡"]
      },
      {
        "chapter_number": 7,
        "chapter_title": "神性的坠落",
        "core_event": "系统自动启动删除程序，沈夜被彻底清除。林清回到监控室，但她的神性已经永远缺失了一块，删除键再也无法使用。",
        "emotional_tone": "空洞的悲伤与永恒的缺失",
        "key_scenes": ["沈夜数据的消散", "林清独自坐在监控室", "无法再按下的删除键", "血条永远停留在满格"]
      }
    ]
  }
}"}

